method below_threshold(l: seq<int>, t: int) returns (result: bool)
    requires |l| > 0 // The list must not be empty
    ensures result == (forall i :: 0 <= i < |l| ==> l[i] < t)
{
    var i: int;
    result := true;
    i := 0;
    while i < |l| && result
        invariant 0 <= i <= |l|
        invariant result == (forall j :: 0 <= j < i ==> l[j] < t)
    {
        if l[i] >= t {
            result := false;
        }
        i := i + 1;
    }
}
